```json
[
    {
        "data": [
            {"company_security_code_portfolio_asset_class": "Equity", "net_exposure": 50000000, "cumulative_pnl": 1500000, ...},
            {"company_security_code_portfolio_asset_class": "Fixed Income", "net_exposure": 20000000, "cumulative_pnl": 300000, ...}
        ],
        "metadata": {"group_by": ["company_security_code_portfolio_asset_class"], "record_count": 2, ...}
    },
    {
        "data": [
            {"company_security_code_portfolio_asset_class": "Equity", "instrument_security_code": "AAPL", "net_exposure": 30000000, ...},
            {"company_security_code_portfolio_asset_class": "Equity", "instrument_security_code": "MSFT", "net_exposure": 20000000, ...},
            {"company_security_code_portfolio_asset_class": "Fixed Income", "instrument_security_code": "UST 10Y", "net_exposure": 20000000, ...}
        ],
        "metadata": {"group_by": ["company_security_code_portfolio_asset_class", "instrument_security_code"], "record_count": 3, ...}
    },
    ...
]
```
