        {"month_label": "Jan 2026", "month_number": 1, "fund_name": "Flagship", "cumulative_pnl_percent_nav": 0.02},
        {"month_label": "Jan 2026", "month_number": 1, "fund_name": "Innovation", "cumulative_pnl_percent_nav": 0.03},
        {"month_label": "Feb 2026", "month_number": 2, "fund_name": "Flagship", "cumulative_pnl_percent_nav": 0.04}
