/**
 * Get alpha analysis statistics for analyst, sector, fund, or other groupings.

Routes between fund-level and non-fund-level alpha based on `group_by`:
- When group_by includes 'fund_name': fund-level metrics with multiple benchmarks
- Otherwise: non-fund-level metrics with a single benchmark

## Fund-level (group_by=['fund_name'])

Uses `benchmark_ids` (multiple). Rows are funds, columns include per-benchmark
RTN and nested alpha objects with SIMPLE and NET ADJ values.

```json
{
    "date_range": {"start_date": "2026-01-01", "end_date": "2026-02-20"},
    "group_by": ["fund_name"],
    "benchmark_ids": ["XBI US Equity", "NBI Index", "RGUSHSBT Index"]
}
```

Example response:
```json
{
    "metadata": {...},
    "data": [
        {
            "fund_name": "Flagship",
            "cumulative_pnl_percent_nav": 0.789,
            "XBI US Equity (RTN)": 0.331,
            "Alpha (% NAV vs XBI US Equity)": {"SIMPLE": 0.458, "NET ADJ": 0.478},
            "NBI Index (RTN)": 0.225,
            "Alpha (% NAV vs NBI Index)": {"SIMPLE": 0.564, "NET ADJ": 0.584}
        }
    ]
}
```

## Non-fund-level (group_by=['primary_analyst'], etc.)

Uses `benchmark_id` (single). Rows are dimension values with flat columns.

```json
{
    "date_range": {"start_date": "2025-01-01", "end_date": "2025-12-01"},
    "filters": {"fund_name": ["Flagship"]},
    "group_by": ["company_subsector"],
    "benchmark_id": "XBI US Equity"
}
```

Example response:
```json
{
    "metadata": {...},
    "benchmark_id": "XBI US Equity",
    "data": [
        {
            "company_subsector": "Therapeutics",
            "cumulative_pnl_percent_nav": 0.86,
            "XBI US Equity (RTN)": 0.33,
            "cumulative_alpha_pnl_percent": 0.25,
            "cumulative_pnl": 2240687723.07
        }
    ]
}
```
 * @summary Get Alpha Analysis Stats
 */
export const getAlphaAnalysisStats = (
  alphaAnalysisRequest: BodyType<AlphaAnalysisRequest>,
  params?: GetAlphaAnalysisStatsParams,
  options?: SecondParameter<typeof customInstance>,
  signal?: AbortSignal
) => {
  return customInstance<GetAlphaAnalysisStats200>(
    {
      url: `/api/dev/portfolio-metrics/alpha-analysis`,
      method: "POST",
      headers: { "Content-Type": "application/json" },
      data: alphaAnalysisRequest,
      params,
      signal,
    },
    options
  );
};

